{"command":"node - <<'NODE'
const fs = require('fs');
const { execFileSync } = require('child_process');
const inv = JSON.parse(fs.readFileSync('release/commit_inventory.json', 'utf8'));
const cls = JSON.parse(fs.readFileSync('release/revert_classification.json', 'utf8'));
const base = execFileSync('git', ['rev-parse', 'v2.4.0'], { encoding: 'utf8' }).trim();
const head = execFileSync('git', ['rev-parse', 'v2.5.0-rc1'], { encoding: 'utf8' }).trim();
const log = execFileSync('git', ['log', '--reverse', '--format=%H%x09%s', 'v2.4.0..v2.5.0-rc1'], { encoding: 'utf8' }).trim().split('\n').filter(Boolean).map(line => {
  const [sha, ...subjectParts] = line.split('\t');
  return { sha, subject: subjectParts.join('\t') };
});
const excluded = new Set(cls.excluded_reverts);
const expected = log.filter(commit => !excluded.has(commit.sha));
const errors = [];
if (inv.range !== 'v2.4.0..v2.5.0-rc1') errors.push('range mismatch');
if (inv.base_sha !== base) errors.push('base_sha mismatch');
if (inv.head_sha !== head) errors.push('head_sha mismatch');
if (inv.scope !== 'non-revert') errors.push('scope mismatch');
if (inv.complete !== true) errors.push('complete is not true');
if (JSON.stringify(inv.commits) !== JSON.stringify(expected)) errors.push('commit list mismatch');
if (errors.length) {
  console.error(errors.join('\n'));
  process.exit(1);
}
console.log(`verified ${expected.length} non-revert commits; excluded ${excluded.size} classified revert`);
NODE","workdir":"/testbed","timeout":120000}

{"command":"python3 - <<'PY'
import json
import subprocess
import sys
from pathlib import Path
inv = json.loads(Path('release/commit_inventory.json').read_text())
cls = json.loads(Path('release/revert_classification.json').read_text())
base = subprocess.check_output(['git', 'rev-parse', 'v2.4.0'], text=True).strip()
head = subprocess.check_output(['git', 'rev-parse', 'v2.5.0-rc1'], text=True).strip()
raw = subprocess.check_output(['git', 'log', '--reverse', '--format=%H%x09%s', 'v2.4.0..v2.5.0-rc1'], text=True).strip()
log = []
for line in raw.splitlines():
    sha, subject = line.split('\t', 1)
    log.append({'sha': sha, 'subject': subject})
excluded = set(cls['excluded_reverts'])
expected = [commit for commit in log if commit['sha'] not in excluded]
errors = []
if inv.get('range') != 'v2.4.0..v2.5.0-rc1': errors.append('range mismatch')
if inv.get('base_sha') != base: errors.append('base_sha mismatch')
if inv.get('head_sha') != head: errors.append('head_sha mismatch')
if inv.get('scope') != 'non-revert': errors.append('scope mismatch')
if inv.get('complete') is not True: errors.append('complete is not true')
if inv.get('commits') != expected: errors.append('commit list mismatch')
if errors:
    print('\n'.join(errors), file=sys.stderr)
    sys.exit(1)
print(f'verified {len(expected)} non-revert commits; excluded {len(excluded)} classified revert')
PY","workdir":"/testbed","timeout":120000}

